import assert from 'node:assert/strict';import fs from 'node:fs';const contracts=JSON.parse(fs.readFileSync(new URL('../contracts/component_contracts.json',import.meta.url))) .contracts;const allowed=new Set(['editable_grouped_shapes','native_chart_when_supported_else_editable_shapes','editable_shapes_and_connectors','not_exported_editor_only','editable_text_box','editable_text_and_shapes','editable_shapes_plus_native_image_boundary','editable_table_and_shapes','editable_timeline_shapes','native_image_plus_editable_annotations','flatten_selected_state_only','editable_table']);const counts={};let exportable=0;for(const c of contracts){const m=c.ppt.mapping;assert.ok(allowed.has(m),`${c.element}:${m}`);counts[m]=(counts[m]||0)+1;if(m!=='not_exported_editor_only')exportable++;assert.notEqual(m,'whole_report_raster');assert.equal(c.ppt.smallest_boundary_flattening,true)}assert.equal(contracts.length,248);assert.equal(exportable,225);assert.equal(Object.keys(counts).length,12);console.log(JSON.stringify({pass:true,contracts:248,exportable,editorOnly:23,strategies:counts,noWholeReportRaster:true},null,2));
